@Composable
fun ConnectivityEvents(onChanged: () -> Unit) {
    val context = LocalContext.current
    val latest by rememberUpdatedState(onChanged)
    DisposableEffect(context) {
        val receiver = object : BroadcastReceiver() {
            override fun onReceive(context: Context, intent: Intent) = latest()
        }
        ContextCompat.registerReceiver(
            context, receiver,
            IntentFilter(ACTION_CONNECTIVITY_CHANGED),
            ContextCompat.RECEIVER_NOT_EXPORTED
        )
        onDispose { context.unregisterReceiver(receiver) }
    }
}

class BootReceiver : BroadcastReceiver() {
    override fun onReceive(context: Context, intent: Intent) {
        if (intent.action != Intent.ACTION_BOOT_COMPLETED) return
        WorkManager.getInstance(context).enqueueUniqueWork(
            "post-boot-sync",
            ExistingWorkPolicy.KEEP,
            OneTimeWorkRequestBuilder<PostBootSyncWorker>().build()
        )
    }
}

fun chatPendingIntent(context: Context, conversationId: String): PendingIntent {
    val intent = Intent(context, MainActivity::class.java).apply {
        action = "OPEN_CHAT"
        data = Uri.parse("upzi://chat/$conversationId")
    }
    return PendingIntent.getActivity(
        context,
        conversationId.hashCode(),
        intent,
        PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
    )
}

val replyIntent = Intent(context, ReplyReceiver::class.java).apply {
    action = ACTION_REPLY
    putExtra(EXTRA_CONVERSATION_ID, conversationId)
}
val replyPendingIntent = PendingIntent.getBroadcast(
    context,
    conversationId.hashCode(),
    replyIntent,
    PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_MUTABLE
)
